import{_ as e,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"DevTools 调试","description":"","frontmatter":{"title":"DevTools 调试","outline":[2,3],"article":{"type":"troubleshooting","structure":"troubleshooting"}},"headers":[],"relativePath":"frontend/guide/core/web/browser/devtools.md","filePath":"frontend/guide/core/web/browser/devtools.md","lastUpdated":1785217527000}'),s={name:"frontend/guide/core/web/browser/devtools.md"};function l(o,a,n,d,h,p){return t(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="devtools-调试" tabindex="-1">DevTools 调试 <a class="header-anchor" href="#devtools-调试" aria-label="Permalink to &quot;DevTools 调试&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>DevTools 的价值不是“知道面板在哪里”，而是把症状转成可复现证据：哪次请求返回了什么、哪个事件修改了 DOM、哪段任务占用主线程、哪个对象仍被引用。正确流程是先固定复现条件，再选择能回答当前问题的面板，最后用修复前后数据验证。</p><p>本篇以 Chrome DevTools 为主要界面，Firefox 与 Safari 有对应能力但名称和布局不同。DevTools 会随版本演进，调试结论应依赖记录数据，而不是固定按钮位置。</p><h2 id="_1-证据优先的调试流程" tabindex="-1">1. 证据优先的调试流程 <a class="header-anchor" href="#_1-证据优先的调试流程" aria-label="Permalink to &quot;1. 证据优先的调试流程&quot;">​</a></h2><h3 id="_1-1-描述症状" tabindex="-1">1.1 描述症状 <a class="header-anchor" href="#_1-1-描述症状" aria-label="Permalink to &quot;1.1 描述症状&quot;">​</a></h3><p>不要从“页面有问题”开始，应记录：</p><ul><li>操作入口与完整步骤；</li><li>预期和实际结果；</li><li>首次出现时间与版本；</li><li>浏览器、设备、账号和网络条件；</li><li>稳定复现还是偶发；</li><li>刷新、无痕、禁用扩展后的差异。</li></ul><h3 id="_1-2-缩小层次" tabindex="-1">1.2 缩小层次 <a class="header-anchor" href="#_1-2-缩小层次" aria-label="Permalink to &quot;1.2 缩小层次&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>第一面板</th></tr></thead><tbody><tr><td>元素样式或位置错误</td><td>Elements</td></tr><tr><td>JavaScript 抛错或状态异常</td><td>Console / Sources</td></tr><tr><td>接口失败、慢或缓存旧响应</td><td>Network</td></tr><tr><td>点击卡顿、动画掉帧</td><td>Performance</td></tr><tr><td>页面越用越占内存</td><td>Memory / Performance</td></tr><tr><td>Service Worker、IndexedDB、Cookie</td><td>Application</td></tr><tr><td>权限、证书和混合内容</td><td>Security / Issues</td></tr></tbody></table><p>一次只回答一个问题，避免同时开所有采样导致噪声。</p><h3 id="_1-3-保留原始证据" tabindex="-1">1.3 保留原始证据 <a class="header-anchor" href="#_1-3-保留原始证据" aria-label="Permalink to &quot;1.3 保留原始证据&quot;">​</a></h3><p>Network 可导出 HAR，Performance 可保存 trace，Memory 可保存 heap snapshot。线上偶发问题应先保留数据，再刷新页面尝试修复。</p><p>HAR、快照和截图可能包含 Cookie、Authorization、请求体和用户数据，分享前必须脱敏。</p><h3 id="_1-4-验证修复" tabindex="-1">1.4 验证修复 <a class="header-anchor" href="#_1-4-验证修复" aria-label="Permalink to &quot;1.4 验证修复&quot;">​</a></h3><p>在相同页面、数据、网络和 CPU 条件下比较修复前后。一次“感觉变快”不能证明原因已经解决。</p><h2 id="_2-elements-dom-与样式" tabindex="-1">2. Elements：DOM 与样式 <a class="header-anchor" href="#_2-elements-dom-与样式" aria-label="Permalink to &quot;2. Elements：DOM 与样式&quot;">​</a></h2><h3 id="_2-1-最终-dom" tabindex="-1">2.1 最终 DOM <a class="header-anchor" href="#_2-1-最终-dom" aria-label="Permalink to &quot;2.1 最终 DOM&quot;">​</a></h3><p>Elements 展示浏览器当前 DOM，不是服务器原始 HTML。它包含脚本修改、解析器纠错、Shadow DOM 和伪元素。</p><p>右键节点可设置 subtree modifications、attribute modifications、node removal 等 DOM breakpoint，在下一次变化发生时暂停到修改代码。</p><h3 id="_2-2-styles" tabindex="-1">2.2 Styles <a class="header-anchor" href="#_2-2-styles" aria-label="Permalink to &quot;2.2 Styles&quot;">​</a></h3><p>Styles 按层叠结果列出匹配规则：</p><ul><li>被划掉表示声明没有赢得层叠；</li><li>灰色或无效提示语法、作用范围或属性不适用；</li><li>可切换 <code>:hover</code>、<code>:focus</code>、<code>:focus-visible</code> 等状态；</li><li>可临时新增声明验证假设。</li></ul><p>DevTools 临时修改不会自动进入源码。确认修复后再改真实文件并重载验证。</p><h3 id="_2-3-computed" tabindex="-1">2.3 Computed <a class="header-anchor" href="#_2-3-computed" aria-label="Permalink to &quot;2.3 Computed&quot;">​</a></h3><p>Computed 显示最终计算值和来源。排查“明明写了 width 为什么结果不同”时，检查：</p><ul><li>box-sizing；</li><li>继承与初始值；</li><li>CSS 变量最终值；</li><li>min / max 约束；</li><li>flex / grid 拉伸；</li><li>transform 与 zoom。</li></ul><h3 id="_2-4-layout-与-layers" tabindex="-1">2.4 Layout 与 Layers <a class="header-anchor" href="#_2-4-layout-与-layers" aria-label="Permalink to &quot;2.4 Layout 与 Layers&quot;">​</a></h3><p>Layout 辅助显示 Grid、Flex、滚动容器和盒模型。Layers / 3D 视图帮助理解合成层，但图层多不等于性能好；应结合 Performance 的 Paint 和 Composite 证据。</p><h3 id="_2-5-accessibility" tabindex="-1">2.5 Accessibility <a class="header-anchor" href="#_2-5-accessibility" aria-label="Permalink to &quot;2.5 Accessibility&quot;">​</a></h3><p>Accessibility 树显示角色、名称、状态和属性来源。排查按钮“看得见但读屏不可用”时，确认原生语义、accessible name、焦点和隐藏状态。</p><h2 id="_3-console-表达式与日志" tabindex="-1">3. Console：表达式与日志 <a class="header-anchor" href="#_3-console-表达式与日志" aria-label="Permalink to &quot;3. Console：表达式与日志&quot;">​</a></h2><h3 id="_3-1-错误上下文" tabindex="-1">3.1 错误上下文 <a class="header-anchor" href="#_3-1-错误上下文" aria-label="Permalink to &quot;3.1 错误上下文&quot;">​</a></h3><p>Console 展示异常、未处理拒绝、资源错误、CSP 和浏览器警告。点击堆栈进入 Sources；先定位最早的根因错误，后续 null 访问可能只是连锁结果。</p><h3 id="_3-2-选中节点" tabindex="-1">3.2 选中节点 <a class="header-anchor" href="#_3-2-选中节点" aria-label="Permalink to &quot;3.2 选中节点&quot;">​</a></h3><p>Elements 当前选中节点可用 <code>$0</code> 访问，之前节点依次为 <code>$1</code> 等：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$0.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getBoundingClientRect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getComputedStyle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($0).display</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这些是 DevTools 命令行辅助，不是页面标准 API，不能写入生产源码。</p><h3 id="_3-3-结构化日志" tabindex="-1">3.3 结构化日志 <a class="header-anchor" href="#_3-3-结构化日志" aria-label="Permalink to &quot;3.3 结构化日志&quot;">​</a></h3><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">table</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(orders)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;checkout&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;normalize&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;unexpected update&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>生产日志不应依赖 Console 作为可观测性系统，也不要输出 token、密码或整份个人数据。</p><h3 id="_3-4-live-expression" tabindex="-1">3.4 Live Expression <a class="header-anchor" href="#_3-4-live-expression" aria-label="Permalink to &quot;3.4 Live Expression&quot;">​</a></h3><p>固定监视一个表达式，例如当前选中元素尺寸、队列长度或全局状态，可观察它随操作变化。表达式本身应轻量，避免每帧执行昂贵查询。</p><h3 id="_3-5-preserve-log" tabindex="-1">3.5 Preserve log <a class="header-anchor" href="#_3-5-preserve-log" aria-label="Permalink to &quot;3.5 Preserve log&quot;">​</a></h3><p>导航问题可开启 Preserve log 保留刷新前日志。保留后要用时间和页面 URL 区分不同文档产生的消息。</p><h2 id="_4-sources-暂停与追踪" tabindex="-1">4. Sources：暂停与追踪 <a class="header-anchor" href="#_4-sources-暂停与追踪" aria-label="Permalink to &quot;4. Sources：暂停与追踪&quot;">​</a></h2><h3 id="_4-1-行断点" tabindex="-1">4.1 行断点 <a class="header-anchor" href="#_4-1-行断点" aria-label="Permalink to &quot;4.1 行断点&quot;">​</a></h3><p>点击行号设置断点，暂停后检查 Scope、Call Stack、Watch 和当前 this。源映射正确时应定位到 TypeScript / 源模块，而不是 bundle。</p><h3 id="_4-2-条件断点与-logpoint" tabindex="-1">4.2 条件断点与 Logpoint <a class="header-anchor" href="#_4-2-条件断点与-logpoint" aria-label="Permalink to &quot;4.2 条件断点与 Logpoint&quot;">​</a></h3><p>条件断点只在表达式为 true 时暂停：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">order.id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;O-1001&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Logpoint 在不修改源码的情况下记录表达式，适合高频路径中只观察特定数据。复杂条件仍会增加执行成本。</p><h3 id="_4-3-事件监听断点" tabindex="-1">4.3 事件监听断点 <a class="header-anchor" href="#_4-3-事件监听断点" aria-label="Permalink to &quot;4.3 事件监听断点&quot;">​</a></h3><p>Event Listener Breakpoints 可在 click、input、timer、XHR/fetch、animation 等事件触发时暂停，适合不知道监听器定义位置的页面。</p><h3 id="_4-4-异常断点" tabindex="-1">4.4 异常断点 <a class="header-anchor" href="#_4-4-异常断点" aria-label="Permalink to &quot;4.4 异常断点&quot;">​</a></h3><p>Pause on uncaught exceptions 只停未捕获异常；勾选 caught exceptions 可观察随后被捕获的异常，但第三方库噪声会明显增加。</p><h3 id="_4-5-dom-breakpoint" tabindex="-1">4.5 DOM breakpoint <a class="header-anchor" href="#_4-5-dom-breakpoint" aria-label="Permalink to &quot;4.5 DOM breakpoint&quot;">​</a></h3><p>当某属性被意外改写或节点突然删除，在 Elements 设置 DOM breakpoint 比轮询 MutationObserver 更能直接定位调用栈。</p><h3 id="_4-6-xhr-fetch-breakpoint" tabindex="-1">4.6 XHR / Fetch breakpoint <a class="header-anchor" href="#_4-6-xhr-fetch-breakpoint" aria-label="Permalink to &quot;4.6 XHR / Fetch breakpoint&quot;">​</a></h3><p>按 URL 子串暂停发送请求的代码。它回答“谁发起了请求”，Network 的 Initiator 则回答完整发起链。</p><h3 id="_4-7-ignore-list" tabindex="-1">4.7 Ignore List <a class="header-anchor" href="#_4-7-ignore-list" aria-label="Permalink to &quot;4.7 Ignore List&quot;">​</a></h3><p>把框架、依赖和打包运行时代码加入 Ignore List，可让单步和异步栈聚焦业务代码。不能因此忽略确实来自依赖的缺陷。</p><h2 id="_5-network-请求证据" tabindex="-1">5. Network：请求证据 <a class="header-anchor" href="#_5-network-请求证据" aria-label="Permalink to &quot;5. Network：请求证据&quot;">​</a></h2><h3 id="_5-1-录制设置" tabindex="-1">5.1 录制设置 <a class="header-anchor" href="#_5-1-录制设置" aria-label="Permalink to &quot;5.1 录制设置&quot;">​</a></h3><p>需要导航请求时先打开 Network，再刷新。Preserve log 保留重定向和跨页记录；Disable cache 通常只在 DevTools 打开时禁用 HTTP cache。</p><h3 id="_5-2-waterfall" tabindex="-1">5.2 Waterfall <a class="header-anchor" href="#_5-2-waterfall" aria-label="Permalink to &quot;5.2 Waterfall&quot;">​</a></h3><p>请求时间大致可能包含：</p><ul><li>Queueing / Stalled；</li><li>DNS；</li><li>Initial connection；</li><li>SSL；</li><li>Request sent；</li><li>Waiting for server response；</li><li>Content download。</li></ul><p>长时间卡在哪一段决定排查方向。Waiting 长不自动等于后端业务慢，还可能包含代理、连接复用和网络链路。</p><h3 id="_5-3-headers" tabindex="-1">5.3 Headers <a class="header-anchor" href="#_5-3-headers" aria-label="Permalink to &quot;5.3 Headers&quot;">​</a></h3><p>检查：</p><ul><li>Request URL、method 和最终 status；</li><li>重定向链；</li><li>Content-Type 与编码；</li><li>Cache-Control、ETag、Age、Vary；</li><li>Origin 与 CORS 响应；</li><li>Cookie 是否发送和被阻止；</li><li>Server-Timing。</li></ul><p>Provisional headers 或警告需要结合请求是否真正发送，不能只截图一行判断。</p><h3 id="_5-4-payload-与-response" tabindex="-1">5.4 Payload 与 Response <a class="header-anchor" href="#_5-4-payload-与-response" aria-label="Permalink to &quot;5.4 Payload 与 Response&quot;">​</a></h3><p>Payload 显示 query、FormData 或请求 body；Preview 是解析后的方便视图，Response 更接近原始内容。确认接口字段时不要只看前端类型声明。</p><h3 id="_5-5-initiator" tabindex="-1">5.5 Initiator <a class="header-anchor" href="#_5-5-initiator" aria-label="Permalink to &quot;5.5 Initiator&quot;">​</a></h3><p>Initiator 展示 parser、script、redirect 或 preload 等发起来源。重复请求要比较调用栈、Request mode、credentials 和 initiator，不只比较 URL。</p><h3 id="_5-6-timing-与优先级" tabindex="-1">5.6 Timing 与优先级 <a class="header-anchor" href="#_5-6-timing-与优先级" aria-label="Permalink to &quot;5.6 Timing 与优先级&quot;">​</a></h3><p>优先级只是浏览器调度信号，资源仍受连接、依赖和服务器影响。Performance 的 Network 轨道可以把请求与主线程解析、脚本和渲染关联起来。</p><h3 id="_5-7-throttling" tabindex="-1">5.7 Throttling <a class="header-anchor" href="#_5-7-throttling" aria-label="Permalink to &quot;5.7 Throttling&quot;">​</a></h3><p>网络预设模拟延迟与吞吐，不等价于真实移动网络抖动、丢包和设备无线栈。关键问题还要在真机和真实网络验证。</p><h2 id="_6-performance-主线程与帧" tabindex="-1">6. Performance：主线程与帧 <a class="header-anchor" href="#_6-performance-主线程与帧" aria-label="Permalink to &quot;6. Performance：主线程与帧&quot;">​</a></h2><h3 id="_6-1-先录最小区间" tabindex="-1">6.1 先录最小区间 <a class="header-anchor" href="#_6-1-先录最小区间" aria-label="Permalink to &quot;6.1 先录最小区间&quot;">​</a></h3><p>开始录制，执行一次问题操作，立即停止。过长 trace 会增加噪声和文件大小。</p><p>录制前固定：</p><ul><li>页面和数据状态；</li><li>是否禁用缓存；</li><li>网络节流；</li><li>CPU 节流；</li><li>屏幕尺寸；</li><li>扩展和 DevTools 自身影响。</li></ul><h3 id="_6-2-时间轴" tabindex="-1">6.2 时间轴 <a class="header-anchor" href="#_6-2-时间轴" aria-label="Permalink to &quot;6.2 时间轴&quot;">​</a></h3><p>重点轨道：</p><table tabindex="0"><thead><tr><th>轨道</th><th>观察</th></tr></thead><tbody><tr><td>Network</td><td>请求与发起关系</td></tr><tr><td>Frames</td><td>掉帧与截图</td></tr><tr><td>Interactions</td><td>输入到下一次呈现</td></tr><tr><td>Main</td><td>task、脚本、样式、布局、绘制</td></tr><tr><td>Compositor / Raster</td><td>合成与光栅</td></tr><tr><td>Timings</td><td>User Timing、LCP、CLS</td></tr></tbody></table><h3 id="_6-3-长任务" tabindex="-1">6.3 长任务 <a class="header-anchor" href="#_6-3-长任务" aria-label="Permalink to &quot;6.3 长任务&quot;">​</a></h3><p>Main 上超过 50ms 的任务会标记长任务区域。展开 Bottom-up 或 Call tree，按 Self time 找真正消耗函数，不要只责怪最外层事件处理器。</p><h3 id="_6-4-forced-reflow" tabindex="-1">6.4 Forced reflow <a class="header-anchor" href="#_6-4-forced-reflow" aria-label="Permalink to &quot;6.4 Forced reflow&quot;">​</a></h3><p>Performance 会标记布局事件和可能的强制回流来源。检查是否在循环中写 DOM 后立即读 offset、scroll 或 getBoundingClientRect。</p><h3 id="_6-5-paint-与-composite" tabindex="-1">6.5 Paint 与 Composite <a class="header-anchor" href="#_6-5-paint-与-composite" aria-label="Permalink to &quot;6.5 Paint 与 Composite&quot;">​</a></h3><p>启用 paint instrumentation 或查看 Layers 可以定位大面积重绘。只看到 Paint 事件不代表它就是瓶颈，要比较持续时间、面积和频率。</p><h3 id="_6-6-cpu-节流" tabindex="-1">6.6 CPU 节流 <a class="header-anchor" href="#_6-6-cpu-节流" aria-label="Permalink to &quot;6.6 CPU 节流&quot;">​</a></h3><p>节流倍率相对当前机器，不等于某款手机 CPU。它适合放大主线程问题和做前后对比，不替代真机测试。</p><h3 id="_6-7-user-timing" tabindex="-1">6.7 User Timing <a class="header-anchor" href="#_6-7-user-timing" aria-label="Permalink to &quot;6.7 User Timing&quot;">​</a></h3><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">performance.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mark</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;orders:start&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loadOrders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">performance.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mark</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;orders:end&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">performance.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">measure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;orders&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;orders:start&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;orders:end&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>自定义 mark 会进入 Performance 记录，适合把业务阶段与浏览器事件关联。命名中不要包含敏感业务数据。</p><h2 id="_7-memory-引用与泄漏" tabindex="-1">7. Memory：引用与泄漏 <a class="header-anchor" href="#_7-memory-引用与泄漏" aria-label="Permalink to &quot;7. Memory：引用与泄漏&quot;">​</a></h2><h3 id="_7-1-先区分增长" tabindex="-1">7.1 先区分增长 <a class="header-anchor" href="#_7-1-先区分增长" aria-label="Permalink to &quot;7.1 先区分增长&quot;">​</a></h3><p>内存增长可能是：</p><ul><li>正常缓存；</li><li>暂时对象尚未 GC；</li><li>DOM 节点或监听器泄漏；</li><li>大 ArrayBuffer / 图片；</li><li>无限列表确实保留更多数据。</li></ul><p>单次任务后的峰值不能直接证明泄漏。</p><h3 id="_7-2-heap-snapshot" tabindex="-1">7.2 Heap snapshot <a class="header-anchor" href="#_7-2-heap-snapshot" aria-label="Permalink to &quot;7.2 Heap snapshot&quot;">​</a></h3><p>常用对比流程：</p><ol><li>进入稳定初始状态并触发 GC。</li><li>保存快照 A。</li><li>重复打开 / 关闭目标组件多次。</li><li>再触发 GC，保存快照 B。</li><li>比较新增对象与 retained size。</li><li>沿 Retainers 查找为什么仍可达。</li></ol><h3 id="_7-3-detached-dom-tree" tabindex="-1">7.3 Detached DOM tree <a class="header-anchor" href="#_7-3-detached-dom-tree" aria-label="Permalink to &quot;7.3 Detached DOM tree&quot;">​</a></h3><p>节点已从 document 移除但仍被 JavaScript 引用时会成为 detached tree。常见引用来自全局数组、闭包、Observer、事件监听和缓存。</p><h3 id="_7-4-allocation-instrumentation" tabindex="-1">7.4 Allocation instrumentation <a class="header-anchor" href="#_7-4-allocation-instrumentation" aria-label="Permalink to &quot;7.4 Allocation instrumentation&quot;">​</a></h3><p>Allocation instrumentation on timeline 记录对象随时间分配和存活，适合操作过程中持续增长问题，但采样开销较大。</p><h3 id="_7-5-performance-monitor" tabindex="-1">7.5 Performance Monitor <a class="header-anchor" href="#_7-5-performance-monitor" aria-label="Permalink to &quot;7.5 Performance Monitor&quot;">​</a></h3><p>实时观察 JS heap、DOM node、listener、layout 和 CPU 趋势，用于快速确认哪个维度随操作增长，再进入快照定位。</p><h2 id="_8-application-存储与离线" tabindex="-1">8. Application：存储与离线 <a class="header-anchor" href="#_8-application-存储与离线" aria-label="Permalink to &quot;8. Application：存储与离线&quot;">​</a></h2><h3 id="_8-1-storage" tabindex="-1">8.1 Storage <a class="header-anchor" href="#_8-1-storage" aria-label="Permalink to &quot;8.1 Storage&quot;">​</a></h3><p>查看和编辑：</p><ul><li>Local / Session Storage；</li><li>IndexedDB 数据库、仓库和索引；</li><li>Cookies 及被阻止原因；</li><li>Cache Storage；</li><li>Storage buckets 与用量（取决于版本）。</li></ul><p>手动编辑只用于复现和验证，应用仍需处理数据损坏。</p><h3 id="_8-2-service-worker" tabindex="-1">8.2 Service Worker <a class="header-anchor" href="#_8-2-service-worker" aria-label="Permalink to &quot;8.2 Service Worker&quot;">​</a></h3><p>检查 registration、scope、状态、更新、clients 和 bypass network。Update on reload 会改变正常生命周期，只在明确测试升级时使用。</p><h3 id="_8-3-clear-site-data" tabindex="-1">8.3 Clear site data <a class="header-anchor" href="#_8-3-clear-site-data" aria-label="Permalink to &quot;8.3 Clear site data&quot;">​</a></h3><p>清理可能包含存储、Cookie、缓存和 Service Worker。执行前记录选项；“清缓存后好了”只说明某层状态参与问题，还没有定位根因。</p><h3 id="_8-4-bfcache" tabindex="-1">8.4 bfcache <a class="header-anchor" href="#_8-4-bfcache" aria-label="Permalink to &quot;8.4 bfcache&quot;">​</a></h3><p>Back/forward cache 测试显示页面是否可缓存及阻止原因。修复后实际执行前进后退，确认 pageshow 恢复逻辑。</p><h3 id="_8-5-manifest" tabindex="-1">8.5 Manifest <a class="header-anchor" href="#_8-5-manifest" aria-label="Permalink to &quot;8.5 Manifest&quot;">​</a></h3><p>PWA Manifest 面板检查解析结果、图标、display 和安装相关错误。Service Worker 可用不代表应用已满足安装或离线要求。</p><h2 id="_9-其他诊断面板" tabindex="-1">9. 其他诊断面板 <a class="header-anchor" href="#_9-其他诊断面板" aria-label="Permalink to &quot;9. 其他诊断面板&quot;">​</a></h2><h3 id="_9-1-issues" tabindex="-1">9.1 Issues <a class="header-anchor" href="#_9-1-issues" aria-label="Permalink to &quot;9.1 Issues&quot;">​</a></h3><p>集中展示 Cookie、CORS、CSP、弃用、可访问性和兼容问题，并链接到受影响资源。Issue 是入口，最终仍要查看 Network、Console 和源码证据。</p><h3 id="_9-2-security" tabindex="-1">9.2 Security <a class="header-anchor" href="#_9-2-security" aria-label="Permalink to &quot;9.2 Security&quot;">​</a></h3><p>查看主文档连接、证书、混合内容和来源安全状态。安全面板显示连接事实，不评价应用授权是否正确。</p><h3 id="_9-3-lighthouse" tabindex="-1">9.3 Lighthouse <a class="header-anchor" href="#_9-3-lighthouse" aria-label="Permalink to &quot;9.3 Lighthouse&quot;">​</a></h3><p>适合自动化审计性能、可访问性、最佳实践和 SEO，结果受环境影响。它提供线索，不替代真实用户数据和手工流程验证。</p><h3 id="_9-4-rendering" tabindex="-1">9.4 Rendering <a class="header-anchor" href="#_9-4-rendering" aria-label="Permalink to &quot;9.4 Rendering&quot;">​</a></h3><p>可开启 Paint flashing、Layout Shift Regions、FPS meter、层边界和媒体特性模拟，快速观察重绘、偏移与无障碍偏好。</p><h3 id="_9-5-coverage" tabindex="-1">9.5 Coverage <a class="header-anchor" href="#_9-5-coverage" aria-label="Permalink to &quot;9.5 Coverage&quot;">​</a></h3><p>记录当前流程实际使用的 CSS / JS 字节。未覆盖代码不一定可删除，可能属于未执行路由；应覆盖代表性流程并结合构建分析。</p><h2 id="_10-本地覆盖与源映射" tabindex="-1">10. 本地覆盖与源映射 <a class="header-anchor" href="#_10-本地覆盖与源映射" aria-label="Permalink to &quot;10. 本地覆盖与源映射&quot;">​</a></h2><h3 id="_10-1-source-map" tabindex="-1">10.1 Source map <a class="header-anchor" href="#_10-1-source-map" aria-label="Permalink to &quot;10.1 Source map&quot;">​</a></h3><p>Source map 把压缩 bundle 映射回源文件。线上公开 source map 可能泄漏源码和路径，应根据部署安全策略决定是否公开或只上传到错误平台。</p><h3 id="_10-2-local-overrides" tabindex="-1">10.2 Local Overrides <a class="header-anchor" href="#_10-2-local-overrides" aria-label="Permalink to &quot;10.2 Local Overrides&quot;">​</a></h3><p>Overrides 可让浏览器用本地内容替代网络资源，适合验证第三方页面或无法立即发布的修改。它可能掩盖真实响应，调试结束要关闭。</p><h3 id="_10-3-workspaces" tabindex="-1">10.3 Workspaces <a class="header-anchor" href="#_10-3-workspaces" aria-label="Permalink to &quot;10.3 Workspaces&quot;">​</a></h3><p>Workspace 将 DevTools 资源映射到本地目录，可直接保存样式和脚本。现代项目通常仍以编辑器和 HMR 为主。</p><h3 id="_10-4-snippets" tabindex="-1">10.4 Snippets <a class="header-anchor" href="#_10-4-snippets" aria-label="Permalink to &quot;10.4 Snippets&quot;">​</a></h3><p>Sources Snippets 保存可重复执行的诊断脚本。不要把含生产凭证或破坏性操作的脚本留给不明确环境。</p><h2 id="_11-完整案例-点击筛选后卡顿" tabindex="-1">11. 完整案例：点击筛选后卡顿 <a class="header-anchor" href="#_11-完整案例-点击筛选后卡顿" aria-label="Permalink to &quot;11. 完整案例：点击筛选后卡顿&quot;">​</a></h2><p>症状：订单页点击“已支付”后约 1.2 秒才更新；Network 中接口 120ms 返回；快速连续点击时页面冻结。</p><h3 id="_11-1-固定复现" tabindex="-1">11.1 固定复现 <a class="header-anchor" href="#_11-1-固定复现" aria-label="Permalink to &quot;11.1 固定复现&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>取值</th></tr></thead><tbody><tr><td>数据</td><td>10,000 条订单</td></tr><tr><td>浏览器</td><td>当前稳定版 Chrome，无扩展 Profile</td></tr><tr><td>CPU</td><td>DevTools 4x slowdown</td></tr><tr><td>Network</td><td>Fast 3G</td></tr><tr><td>操作</td><td>加载完成后点击一次“已支付”</td></tr><tr><td>对照</td><td>1,000 条订单同操作</td></tr></tbody></table><h3 id="_11-2-network-证据" tabindex="-1">11.2 Network 证据 <a class="header-anchor" href="#_11-2-network-证据" aria-label="Permalink to &quot;11.2 Network 证据&quot;">​</a></h3><ul><li>请求只发送一次；</li><li>TTFB 82ms，总耗时 121ms；</li><li>响应大小 34KB；</li><li>无重定向、CORS 或缓存异常。</li></ul><p>结论：网络不是 1.2 秒等待的主要来源。</p><h3 id="_11-3-performance-证据" tabindex="-1">11.3 Performance 证据 <a class="header-anchor" href="#_11-3-performance-证据" aria-label="Permalink to &quot;11.3 Performance 证据&quot;">​</a></h3><ul><li>click 后出现 1,037ms 长任务；</li><li>其中 <code>filterOrders</code> Self time 312ms；</li><li>随后创建 9,842 个 li；</li><li>Layout 168ms，Paint 96ms；</li><li>连续点击在任务队列继续排队。</li></ul><p>结论：同步过滤和全量 DOM 重建共同阻塞主线程。</p><h3 id="_11-4-memory-证据" tabindex="-1">11.4 Memory 证据 <a class="header-anchor" href="#_11-4-memory-证据" aria-label="Permalink to &quot;11.4 Memory 证据&quot;">​</a></h3><p>重复筛选后 DOM node 数回落，没有持续 detached tree 增长。Heap 在 GC 后接近初始值。</p><p>结论：这是每次操作成本过高，不是已证明的泄漏。</p><h3 id="_11-5-修复" tabindex="-1">11.5 修复 <a class="header-anchor" href="#_11-5-修复" aria-label="Permalink to &quot;11.5 修复&quot;">​</a></h3><ol><li>服务端只返回当前页和当前筛选结果。</li><li>前端保留稳定容器，不重建不可见 10,000 行。</li><li>使用分页或虚拟列表限制 DOM 数量。</li><li>取消前一次未完成筛选请求。</li><li>为筛选入口增加 User Timing。</li></ol><h3 id="_11-6-回归数据" tabindex="-1">11.6 回归数据 <a class="header-anchor" href="#_11-6-回归数据" aria-label="Permalink to &quot;11.6 回归数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">修复前</th><th style="text-align:right;">修复后</th></tr></thead><tbody><tr><td>数据行</td><td style="text-align:right;">10,000</td><td style="text-align:right;">100</td></tr><tr><td>最长 task</td><td style="text-align:right;">1,037ms</td><td style="text-align:right;">42ms</td></tr><tr><td>Layout</td><td style="text-align:right;">168ms</td><td style="text-align:right;">9ms</td></tr><tr><td>Paint</td><td style="text-align:right;">96ms</td><td style="text-align:right;">7ms</td></tr><tr><td>操作到呈现</td><td style="text-align:right;">1,210ms</td><td style="text-align:right;">184ms</td></tr><tr><td>重复操作后 DOM node</td><td style="text-align:right;">持续约 10,600</td><td style="text-align:right;">约 430</td></tr></tbody></table><p>修复结论来自相同节流和数据条件下的 trace，而不是只看到接口变快。</p><h2 id="_12-症状与工具速查" tabindex="-1">12. 症状与工具速查 <a class="header-anchor" href="#_12-症状与工具速查" aria-label="Permalink to &quot;12. 症状与工具速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>首查</th><th>关键证据</th></tr></thead><tbody><tr><td>样式不生效</td><td>Elements / Styles</td><td>规则来源、层叠、计算值</td></tr><tr><td>DOM 被意外删除</td><td>DOM breakpoint</td><td>修改调用栈</td></tr><tr><td>点击没发请求</td><td>Sources / Network</td><td>事件断点、Initiator</td></tr><tr><td>请求慢</td><td>Network Timing</td><td>DNS、连接、TTFB、下载</td></tr><tr><td>接口快但页面慢</td><td>Performance</td><td>长任务、布局、绘制</td></tr><tr><td>页面越用越卡</td><td>Memory</td><td>Retainers、detached tree</td></tr><tr><td>刷新后仍旧资源</td><td>Network / Application</td><td>HTTP cache、SW、Cache API</td></tr><tr><td>后退状态错误</td><td>Application bfcache</td><td>资格、pageshow 恢复</td></tr><tr><td>Cookie 不发送</td><td>Network / Issues</td><td>SameSite、Domain、Secure、CORS</td></tr><tr><td>真机才出现</td><td>Remote debugging</td><td>实际设备 trace 与日志</td></tr></tbody></table><h2 id="_13-常见错误" tabindex="-1">13. 常见错误 <a class="header-anchor" href="#_13-常见错误" aria-label="Permalink to &quot;13. 常见错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>修正</th></tr></thead><tbody><tr><td>打开面板后随意点击</td><td>先写稳定复现步骤</td></tr><tr><td>只看 Console 最后一条错误</td><td>找最早根因和完整堆栈</td></tr><tr><td>Disable cache 当清全部数据</td><td>区分 HTTP cache、SW 和存储</td></tr><tr><td>看到长函数就立刻重写</td><td>展开 Bottom-up 看 Self time</td></tr><tr><td>内存上涨一次就称泄漏</td><td>GC 后做多轮快照对比</td></tr><tr><td>节流结果当真实设备数值</td><td>用于对比，再做真机验证</td></tr><tr><td>DevTools 临时改样式后结束</td><td>修改源码并重新加载验证</td></tr><tr><td>分享未脱敏 HAR / snapshot</td><td>清理凭证和用户数据</td></tr></tbody></table><h2 id="_14-参考资料" tabindex="-1">14. 参考资料 <a class="header-anchor" href="#_14-参考资料" aria-label="Permalink to &quot;14. 参考资料&quot;">​</a></h2><ul><li><a href="https://developer.chrome.com/docs/devtools/" target="_blank" rel="noreferrer">Chrome DevTools Documentation</a></li><li><a href="https://developer.chrome.com/docs/devtools/performance/reference/" target="_blank" rel="noreferrer">Chrome DevTools：Performance features reference</a></li><li><a href="https://developer.chrome.com/docs/devtools/network/" target="_blank" rel="noreferrer">Chrome DevTools：Inspect network activity</a></li><li><a href="https://developer.chrome.com/docs/devtools/memory-problems/" target="_blank" rel="noreferrer">Chrome DevTools：Memory problems</a></li><li><a href="https://developer.chrome.com/docs/devtools/application/" target="_blank" rel="noreferrer">Chrome DevTools：Application panel</a></li><li><a href="https://firefox-source-docs.mozilla.org/devtools-user/" target="_blank" rel="noreferrer">Firefox Developer Tools</a></li></ul>`,171)])])}const k=e(s,[["render",l]]);export{u as __pageData,k as default};
